'use client';

import { useSyncExternalStore } from 'react';
import { readResolvedTheme, subscribeToTheme, type ResolvedTheme } from './theme';

/**
 * Tracks the theme that is actually painted on screen. Used by components that
 * cannot be styled with CSS alone (e.g. SVG generated by Mermaid).
 */
export function useResolvedTheme(): ResolvedTheme {
  return useSyncExternalStore(
    subscribeToTheme,
    readResolvedTheme,
    () => 'light' as ResolvedTheme,
  );
}
